<?php require __DIR__.'/../includes/bootstrap.php'; $error=''; $id=(int)($_SESSION['verify_user_id']??0); if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$code=strtoupper(trim($_POST['code']??''));$s=db()->prepare('SELECT * FROM email_verifications WHERE user_id=? AND verified_at IS NULL ORDER BY id DESC LIMIT 1');$s->execute([$id]);$v=$s->fetch();if(!$v||$v['attempts']>=5||strtotime($v['expires_at'])<time())$error='This authentication code has expired.';elseif(strlen($code)!==15||!password_verify($code,$v['verification_code_hash'])){db()->prepare('UPDATE email_verifications SET attempts=attempts+1 WHERE id=?')->execute([$v['id']]);$error='Invalid authentication code.';}else{db()->prepare('UPDATE email_verifications SET verified_at=NOW() WHERE id=?')->execute([$v['id']]);db()->prepare("UPDATE users SET email_verified=1,status='ACTIVE',verified_at=NOW() WHERE id=?")->execute([$id]);unset($_SESSION['dev_verification_code']);flash('success','Your account is verified. Please sign in.');header('Location: login.php');exit;}} $pageTitle='Verify account';require __DIR__.'/../includes/header.php';?><div class="panel"><h1>Verify your HOTELRESERVE account</h1><p>Enter the 15-character authentication code.</p><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><?php if(!empty($_SESSION['dev_verification_code'])):?><div class="alert warning">Development code: <?=e($_SESSION['dev_verification_code'])?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Authentication code</label><input required maxlength="15" pattern="[A-Za-z0-9]{15}" name="code" autocomplete="one-time-code"><p><button>Verify account</button> <a class="btn small" href="resend-code.php">Resend code</a></p></form></div><?php require __DIR__.'/../includes/footer.php'; ?>
